const d = n => { const t = new Date(Date.now() - n*86400000); return t.toISOString().slice(0,16).replace('T',' '); };
return [
 { json: { 'Timestamp': d(2),  'First Name':'Karim',  'Last Name':'Mammen', 'Phone':'(503)954-9211',
           'Searched Address':'8624 Fanellanwood Pl, Dallas, TX 75238', 'Lead Type':'Seller', 'Status':'' } },
 { json: { 'Timestamp': d(12), 'First Name':'Andrew', 'Last Name':'Ikall',  'Phone':'2148869969',
           'Searched Address':'921 Glen Stone Ln, Dallas, TX 75232', 'Lead Type':'Seller', 'Status':'' } },
 { json: { 'Timestamp': d(6),  'First Name':'Sample', 'Last Name':'Buyer',  'Phone':'(214)555-0142',
           'Searched Address':'', 'Lead Type':'General', 'Status':'' } },
 { json: { 'Timestamp': d(2),  'First Name':'Already','Last Name':'Handled','Phone':'(214)555-0199',
           'Searched Address':'123 Test St', 'Lead Type':'Seller', 'Status':'Replied' } }
];

const rows = $input.all().map(i => i.json);
const now = new Date();
const DONE = /^(replied|responded|dead|closed|won|lost|unsubscribed|do not contact|no contact)$/i;
const days = d => { const t = new Date(d); return isNaN(t) ? null : Math.floor((now - t) / 86400000); };
const pretty = p => { const d = String(p||'').replace(/\D/g,'').slice(-10);
  return d.length===10 ? '('+d.slice(0,3)+') '+d.slice(3,6)+'-'+d.slice(6) : String(p||''); };

const due = [], stale = [];
for (const r of rows) {
  const status = String(r['Status'] || '').trim();
  if (DONE.test(status)) continue;
  const age = days(r['Timestamp']);
  if (age === null || age < 2 || age > 30) continue;
  const first = String(r['First Name'] || '').trim() || 'there';
  const addr  = String(r['Searched Address'] || '').trim();
  const where = addr ? addr.split(',')[0] : '';
  const phone = pretty(r['Phone']);
  if (!phone) continue;

  const msg2 = where
    ? 'Hey ' + first + ', it\'s Hector again. Still want to connect about ' + where + '. Is morning or evening easier for a quick call? Or if texting is simpler, tell me a little about the place and I can start there.'
    : 'Hey ' + first + ', it\'s Hector again. Still want to hear what you\'re looking for. Is morning or evening better for a quick call? Or just text me what you\'re after and I\'ll take it from there.';
  const msg12 = 'Hey ' + first + ', last one from me. Are you looking to sell this year, or is it more of a someday thing? Either answer is fine, I just want to know whether to keep in touch or leave you alone.';

  const base = { first, last: String(r['Last Name']||'').trim(), phone, addr, age,
                 type: String(r['Lead Type']||'').trim(), status };
  if (age === 2)       due.push({ ...base, touch: 'Day 2',  msg: msg2 });
  else if (age === 12) due.push({ ...base, touch: 'Day 12', msg: msg12 });
  else if (!status)    stale.push(base);
}

if (!due.length && !stale.length) return [];

const line = d => d.first + ' ' + d.last + '  —  ' + d.touch + (d.addr ? '  ·  ' + d.addr : '') +
  '\n' + d.phone + '\n\nSuggested:\n"' + d.msg + '"\n' + '-'.repeat(46);
let body = '';
if (due.length) body += 'TEXT TODAY (' + due.length + ')\n' + '='.repeat(46) + '\n' + due.map(line).join('\n') + '\n\n';
if (stale.length) body += 'STILL OPEN, NO STATUS SET (' + stale.length + ')\n' + '='.repeat(46) + '\n' +
  stale.map(d => d.first + ' ' + d.last + '  ·  day ' + d.age + '  ·  ' + d.phone + (d.addr ? '  ·  ' + d.addr : '')).join('\n') +
  '\n\nSet Status in Database > Leads once you have talked to them and they will drop off this list.\n';

return [{ json: { count: due.length, staleCount: stale.length, body,
  subject: due.length ? 'Follow up today: ' + due.length + ' lead' + (due.length>1?'s':'') : 'Open leads: nothing due today' } }];
